  for (const p of pages.slice(0, 10)) {
    const text = (p.raw_content || p.content || '').slice(0, 2000);
    if (text.length < 500) continue;
    out.push({ json: { url: p.url, title: p.title || blogName, content: text, blog: blogName } });
