parameters.jsCode:
// Pre-flight blocked this strategy because a prior quantum_mc_run produced UCI > threshold.
// Tier 6: cache-READ-ONLY gate. The strategy is dropped from this cycle to avoid
// re-running an already-failed prop-firm UCI test. Counts as a graveyard signal.
const input = $input.first().json;
return [{
  json: {
    skipped: true,
    reason: 'quantum_pre_flight_failed',
    score: input.score,
    qmcRunId: input.qmcRunId,
    backtestId: input.backtestId,
    threshold: input.threshold,
    workflowRunId: input.workflowRunId
  }
}];

const response = $input.first().json;
const decisions = response.decisions || response.data || response;
const decisionList = Array.isArray(decisions) ? decisions : [];

let approved = 0;
let blocked = 0;
let restricted = 0;
const blockedDetails = [];

for (const d of decisionList) {
  const decision = (d.finalDecision || d.decision || '').toUpperCase();
  if (decision === 'APPROVED') approved++;
  else if (decision === 'BLOCKED') {
    blocked++;
    blockedDetails.push({
      strategyId: d.strategyId || d.strategy_id || 'N/A',
      firm: d.firm || d.firmName || 'N/A',
      reason: d.reason || d.blockReason || 'No reason provided',
      ruleset: d.ruleset || 'N/A'
    });
  } else if (decision === 'RESTRICTED') restricted++;
}

return [{
  json: {
    summary: {
      approved,
      blocked,
      restricted,
      total: decisionList.length
    },
    blockedCount: blocked,
    blockedDetails,
    gateCheckTime: new Date().toISOString()
  }
}];

const data = $input.first().json;
const blocked = data.blockedDetails || [];

const details = blocked.map(b =>
  `  - Strategy ${b.strategyId} (Firm: ${b.firm})\n    Reason: ${b.reason}`
).join('\n\n');

return [{
  json: {
    title: 'Pre-Session Gate: Strategies Blocked',
    message: `${blocked.length} strategy(ies) BLOCKED\n\n${details}\n\nSummary: ${data.summary.approved} approved, ${data.summary.blocked} blocked, ${data.summary.restricted} restricted (${data.summary.total} total)\nChecked at: ${data.gateCheckTime}`,
    severity: 'warning',
    data: {
      approved: String(data.summary.approved),
      blocked: String(data.summary.blocked),
      restricted: String(data.summary.restricted),
