  { name: 'Discord Bot', port: 4100, critical: false, result: $('Check Discord Bot').first() },
];

function inspectService(service) {
  const json = service.result?.json ?? {};
  const error = json.error || json.message || json.errorMessage || json.description || null;
  const code = json.code || json.errorCode || json.statusCode || null;
  const healthy = !error && (
    json.status === 'ok'
    || json.connected === true
    || Array.isArray(json.models)
  );

  return {
    name: service.name,
    port: service.port,
    critical: service.critical,
    healthy,
    status: json.status ?? (healthy ? 'ok' : 'error'),
    error: error || (healthy ? null : code || 'no response'),
  };
}

const inspected = services.map(inspectService);
const failures = inspected.filter((service) => !service.healthy);

return [{
  json: {
    allHealthy: failures.length === 0,
    failureCount: failures.length,
    failures: failures.map((service) => `${service.name} (port ${service.port}): ${service.error}`),
    services: inspected,
    checkedAt: new Date().toISOString(),
  },
}];

