const response = $input.first().json;

const decisions = Array.isArray(response) ? response : (response.decisions || response.data || []);

const trade = [];
const reduce = [];
const skip = [];

for (const d of decisions) {
  const name = d.strategyName || d.strategy || d.name || 'Unknown';
  const reason = d.reason || d.rationale || '';
  const decision = (d.decision || d.action || 'TRADE').toUpperCase();

  if (decision === 'SKIP') {
    skip.push({ name, reason });
  } else if (decision === 'REDUCE') {
    reduce.push({ name, reason });
  } else {
    trade.push({ name, reason });
  }
}

return [{
  json: {
    hasSkips: skip.length > 0,
    hasReduces: reduce.length > 0,
    trade,
    reduce,
    skip,
    totalStrategies: decisions.length,
    timestamp: new Date().toISOString()
  }
}];

